/** Original, bilingual Senior 1 micro-inquiries. No learner expression is executed. */
const B=(en,zh)=>({en,'zh-Hant':zh});
const P=s=>{const [en,zh]=s.split('｜');return B(en,zh);};
const L=(pair,locale)=>pair[locale==='zh-Hant'?'zh-Hant':'en'];
const N=(key,label,min,max,step=1)=>({key,label:P(label),min,max,step});
const S=(key,label,options)=>({key,label:P(label),options:options.map(([value,text])=>({value,label:P(text)}))});
const C=(label,params,boundary=false)=>({label:P(label),params,boundary});
const observe=B('Finite displayed cases suggest a conjecture; the justification below states why it holds under the stated conditions.','畫面上的有限例子用來形成猜想；下方論證說明它在所列條件下為何成立。');
function A(chapter,order,title,question,prediction,explanation,conditions,misconception,challenge,proof,teacherPrompt,exitPrompt,exitAnswer,cases,controls,prerequisites){
  const explain=P(explanation);
  return {id:`g10-${chapter}-${String(order).padStart(2,'0')}`,chapter,order,title:P(title),question:P(question),prediction:P(prediction),explanation:B(`${explain.en} ${observe.en}`,`${explain['zh-Hant']} ${observe['zh-Hant']}`),conditions:P(conditions),misconception:P(misconception),challenge:P(challenge),proof:P(proof),teacherPrompt:P(teacherPrompt),exit:{prompt:P(exitPrompt),answer:P(exitAnswer)},cases,controls,prerequisites:P(prerequisites)};
}

export const activities=[
 A('01',1,'An element or a subset?｜元素還是子集？','Does changing 3 into {3} change the question?｜把 3 改寫成 {3}，問題會改變嗎？','Predict whether a number, its singleton and the empty set belong to A or are subsets of A.｜先預測一個數、其單元素集及空集，哪些屬於 A、哪些包含於 A。','A contains numbers. A number can be an element; a singleton is a subset exactly when its number belongs to A.｜A 的元素是數；數可以是元素，而單元素集是子集恰好當其數屬於 A。','The universe is {1,…,8}; A is the chosen numeric set. A subset question requires a set as its left operand.｜全集為 {1,…,8}；A 是選定的數集；子集關係左方必須是集合。','Membership and inclusion are different relations; the empty set is not the number zero.｜屬於與包含是不同關係；空集不是數字零。','Construct a set whose elements are themselves sets, then reconsider membership.｜構造元素本身也是集合的集合，再重新判斷屬於關係。','{n} ⊆ A means every element of {n}, namely n, is in A. The empty set has no element violating inclusion.｜{n}⊆A 的意思是 {n} 的每個元素，即 n，都在 A；空集沒有違反包含要求的元素。','Ask pupils to name the type of the object before choosing a symbol.｜先請學生說出物件類型，再選關係符號。','For A={2,4}, compare 2∈A, {2}⊆A and {2}∈A.｜A={2,4}，比較 2∈A、{2}⊆A、{2}∈A。','True, true, false; A contains numbers, not singleton sets.｜真、真、假；A 的元素是數，不是單元素集。',[C('A member｜集合內的數',{n:2,object:'number',set:'even'}),C('Its singleton｜它的單元素集',{n:2,object:'singleton',set:'even'}),C('The empty set｜空集',{n:3,object:'empty',set:'even'},true)],[N('n','Number n｜數 n',1,8),S('object','Object｜物件',[['number','n｜n'],['singleton','{n}｜{n}'],['empty','Empty set｜空集']]),S('set','Set A｜集合 A',[['even','Even numbers｜偶數'],['first','Numbers 1–4｜1 至 4']])],'Numbers and braces｜數與大括號'),
 A('01',2,'Containment, equality and the empty set｜包含、相等與空集','When is a subset proper?｜子集何時是真子集？','Compare A={1,…,a} and B={1,…,b}; predict the relation when a=b or a=0.｜比較 A={1,…,a}、B={1,…,b}；預測 a=b 或 a=0 的情況。','A⊆B allows equality. A proper subset additionally requires an element of B outside A.｜A⊆B 容許相等；真子集另外要求 B 有元素不在 A。','a and b are integers from 0 to 8; an upper bound of zero denotes the empty set.｜a、b 是 0 至 8 的整數；上界為零表示空集。','An empty set is a subset of itself but not a proper subset of itself.｜空集是自身的子集，但不是自身的真子集。','Describe all pairs (a,b) giving A⊊B without listing every set.｜不用逐一列集，描述所有使 A⊊B 的 (a,b)。','For these initial segments, a≤b gives inclusion; a>b leaves a in A outside B. Equality holds iff a=b.｜對這些初段整數集，a≤b 即包含；a>b 時 A 的 a 不在 B；相等當且僅當 a=b。','Request an explicit witness whenever inclusion fails.｜包含不成立時，要求指出一個明確反例元素。','Is ∅ a proper subset of {1}? Is ∅ a proper subset of ∅?｜∅ 是 {1} 的真子集嗎？∅ 是 ∅ 的真子集嗎？','Yes; no. The second pair is equal.｜是；不是。第二對集合相等。',[C('Proper inclusion｜真包含',{a:3,b:5}),C('Equal sets｜集合相等',{a:4,b:4},true),C('Both empty｜兩者皆空',{a:0,b:0},true)],[N('a','Upper bound a｜上界 a',0,8),N('b','Upper bound b｜上界 b',0,8)],'Set notation｜集合表示'),
 A('01',3,'Operations select different elements｜不同運算選出哪些元素？','Can union, intersection and difference use the same rule?｜聯集、交集與差集可以用同一規則嗎？','Choose A and B, predict which chips remain, then change only the operation.｜選定 A、B，預測哪些數牌留下，再只改運算。','The decision for each element is respectively OR, AND, A-and-not-B, or not-A in U.｜逐元素的判準分別是「或」、「且」、「在 A 不在 B」或「全集內不在 A」。','U={1,…,8}; A={1,…,a}; B={b,…,8}. b=9 means B is empty.｜U={1,…,8}；A={1,…,a}；B={b,…,8}；b=9 表示 B 為空。','A−B need not equal B−A; a complement depends on its universe.｜A−B 未必等於 B−A；補集必須依所定全集。','Use element-by-element decisions to explain a De Morgan identity.｜用逐元素判斷解釋一條德摩根定律。','For any x∈U, membership of the result is determined by its two truth values x∈A and x∈B. The displayed four regions partition U.｜每個 x∈U 是否在結果，取決於 x∈A、x∈B 兩個真假值；圖中四區把 U 分割。','Ask for one element distinguishing two operations.｜請學生找一個能區分兩種運算的元素。','If A={1,2}, B={2,3}, find A−B and A∩B.｜A={1,2}、B={2,3}，求 A−B 及 A∩B。','A−B={1}; A∩B={2}.｜A−B={1}；A∩B={2}。',[C('Intersection｜交集',{a:5,b:3,op:'intersection'}),C('Difference｜差集',{a:5,b:3,op:'difference'}),C('Empty A, complement｜A 為空時的補集',{a:0,b:9,op:'complement'},true)],[N('a','A ends at a｜A 的上界 a',0,8),N('b','B starts at b｜B 的下界 b',1,9),S('op','Operation｜運算',[['intersection','Intersection｜交集'],['union','Union｜聯集'],['difference','A minus B｜A 差 B'],['complement','Complement of A｜A 的補集']])],'Membership｜元素歸屬'),
 A('01',4,'Can these class counts coexist?｜這組人數可以同時成立嗎？','How many pupils choose neither option?｜有多少人兩項都沒選？','Predict four disjoint category counts before changing the overlap.｜改變重疊人數前，先預測四個互不重疊類別的人數。','The overlap is counted twice in a+b, so subtract it once. Invalid negative categories signal inconsistent data.｜a+b 把交集計了兩次，須減一次；類別出現負數表示資料矛盾。','Counts are integers; 0≤overlap≤min(a,b), and a+b−overlap≤N.｜人數為整數；0≤交集≤min(a,b)，且 a+b−交集≤N。','An overlap cannot be chosen independently of the class total and margins.｜交集人數不能脫離總數及兩類人數任意選取。','Derive the smallest and largest possible overlap from N,a,b.｜由 N、a、b 推出交集可能的最小及最大值。','The categories are a−o, b−o, o and N−a−b+o. Nonnegativity gives max(0,a+b−N)≤o≤min(a,b).｜四類是 a−o、b−o、o、N−a−b+o；非負要求給出 max(0,a+b−N)≤o≤min(a,b)。','Keep an impossible case on screen and ask which assumption it violates.｜保留不可能案例，請學生指出違反哪項條件。','N=30,a=20,b=18: can the overlap be 5?｜N=30、a=20、b=18，交集可否為 5？','No; the union would be 33, exceeding 30. The overlap must be at least 8.｜不能；聯集會是 33，超過 30；交集至少 8。',[C('A feasible survey｜可行調查',{total:40,a:24,b:21,overlap:10}),C('No one chooses neither｜沒有人兩者皆不選',{total:30,a:20,b:18,overlap:8},true),C('Impossible margins｜矛盾人數',{total:30,a:20,b:18,overlap:5},true)],[N('total','Class total N｜全班人數 N',1,60),N('a','Choose A｜選 A 人數',0,60),N('b','Choose B｜選 B 人數',0,60),N('overlap','Choose both｜兩者皆選',0,60)],'Set operations and integer counts｜集合運算與整數計數'),
 A('02',1,'A counterexample to an implication｜命題的反例','When does p⇒q fail?｜p⇒q 何時不成立？','Test p: x>c and q: x>0; predict the one truth-value combination that refutes p⇒q.｜檢查 p：x>c、q：x>0；預測哪一組真假值能推翻 p⇒q。','A counterexample needs p true and q false. A case with p false does not refute the implication.｜反例須 p 真而 q 假；p 假的案例不能推翻此蘊含。','x and c are real numbers. A displayed test at one x is distinct from the claim for every x.｜x、c 為實數；某個 x 的檢查不同於對所有 x 的主張。','Finding q true does not establish p; the converse is a separate statement.｜q 真不能推出 p；逆命題須另行檢查。','Choose c for which the forward implication always holds but the converse fails.｜選一個 c，使正向恆成立、逆向卻有反例。','By the definition of implication, only true⇒false fails. For example c<0 permits a point c<x≤0 as a refutation.｜依蘊含定義，只有「真推出假」不成立；例如 c<0 時，c<x≤0 的點就是反例。','Ask whether each example refutes, supports locally, or leaves a universal claim unproved.｜問每例是反例、局部支持，還是仍未證明全稱主張。','Does x=−1 refute x>−2 ⇒ x>0?｜x=−1 能否推翻 x>−2 ⇒ x>0？','Yes: −1>−2 but −1 is not positive.｜能：−1>−2，但 −1 不是正數。',[C('Both true｜兩者皆真',{x:2,c:1}),C('A refuting witness｜反例',{x:-1,c:-2},true),C('False premise｜前件為假',{x:-2,c:1},true)],[N('x','Test value x｜測試值 x',-5,5,.5),N('c','Threshold c｜門檻 c',-4,4,.5)],'Inequalities and truth values｜不等式與真假'),
 A('02',2,'Necessary or sufficient?｜必要還是充分？','Which interval is contained in which?｜哪個區間包含於哪個區間？','For p:x>a and q:x>b, predict both implication directions when a<b, a=b and a>b.｜p：x>a、q：x>b；預測 a<b、a=b、a>b 時兩個方向。','Sufficiency is containment of the p-solution set in the q-solution set; necessity reverses this containment.｜充分性是 p 的解集包含於 q 的解集；必要性則把包含方向反過來。','Both inequalities are strict and share the real-number universe.｜兩式均為嚴格不等式，全集同為實數。','A single common solution proves neither implication universally.｜一個共同解不能證明任一方向普遍成立。','Replace one strict inequality by a non-strict one and examine equal thresholds.｜把一式改為非嚴格不等式，研究門檻相同的情況。','If a≥b, x>a implies x>b. If a<b, the midpoint (a+b)/2 satisfies p and not q. Thus the comparison completely classifies the directions.｜a≥b 時，x>a 必有 x>b；a<b 時，中點 (a+b)/2 滿足 p 而不滿足 q，因此門檻比較完整判定兩方向。','Require a general interval argument and a witness for the failing direction.｜要求給一般區間論證，並為不成立方向給反例。','x>3 is what condition for x>1?｜x>3 是 x>1 的甚麼條件？','Sufficient but not necessary; x=2 refutes the converse.｜充分不必要；x=2 推翻逆向。',[C('Sufficient only｜充分不必要',{a:3,b:1}),C('Equivalent｜充要',{a:2,b:2},true),C('Necessary only｜必要不充分',{a:-1,b:2})],[N('a','Threshold in p｜p 的門檻 a',-4,4,.5),N('b','Threshold in q｜q 的門檻 b',-4,4,.5)],'Implications and intervals｜蘊含與區間'),
 A('02',3,'All or at least one?｜所有還是至少一個？','Can a statement be existentially true but universally false?｜同一性質能否存在命題真、全稱命題假？','For x²≥k or x²>k, compare a finite integer domain with all real numbers.｜對 x²≥k 或 x²>k，比較有限整數域與全體實數域。','All requires every allowed input; existence requires one. Enlarging the domain can change these conclusions differently.｜全稱要求每個允許輸入；存在只需一個；擴大定義域可使兩者有不同變化。','The finite domain is {−n,…,n}, n≥1. The alternative domain is R.｜有限域是 {−n,…,n}，n≥1；另一選項為 R。','Checking the plotted real inputs is not checking every real number.｜檢查圖上幾個實數，不是檢查全部實數。','Find k for which the finite domain has no witness but R has one.｜找一個 k，使有限域沒有見證，而 R 有。','The minimum square is 0. On the finite domain the maximum is n²; on R squares are unbounded. These bounds decide all and existence exactly.｜平方最小值是 0；有限域最大為 n²，R 上平方無上界；這些界精確判定全稱與存在。','Ask pupils to distinguish a witness from a complete proof over R.｜請學生區分一個見證與 R 上的完整證明。','Over R, compare ∀x:x²≥1 and ∃x:x²≥1.｜在 R 上比較 ∀x：x²≥1 與 ∃x：x²≥1。','The universal claim is false at 0; the existential claim is true at 1.｜全稱在 0 處為假；存在由 1 作見證為真。',[C('Existence without universality｜存在真而全稱假',{n:2,k:1,strict:'no',domain:'finite'}),C('Boundary at zero｜零的邊界',{n:2,k:0,strict:'yes',domain:'real'},true),C('Finite domain exhausted｜有限域沒有見證',{n:2,k:5,strict:'no',domain:'finite'},true)],[N('n','Finite bound n｜有限域上界 n',1,5),N('k','Square threshold k｜平方門檻 k',-2,30),S('strict','Comparison｜比較',[['no','x² ≥ k｜x² ≥ k'],['yes','x² > k｜x² > k']]),S('domain','Domain｜定義域',[['finite','Integers −n to n｜整數 −n 至 n'],['real','All real numbers｜所有實數']])],'Squares and quantifier language｜平方與量詞'),
 A('02',4,'Negating a quantified statement｜否定帶量詞命題','Does negating “all are greater” mean “all are smaller”?｜否定「全部較大」是否等於「全部較小」？','Predict the negation of ∀x:x²>k and ∃x:x²>k on [−n,n].｜預測 [−n,n] 上 ∀x：x²>k 與 ∃x：x²>k 的否定。','Negation switches all and exists and replaces > by ≤. Equality belongs to the negation.｜否定要交換全稱與存在，並把 > 改為 ≤；等號屬於否定一方。','The domain is the entire real interval [−n,n], with n>0.｜定義域為完整實區間 [−n,n]，n>0。','Not all is not the same as none.｜「並非全部」不等於「全部都不」。','Negate an inequality with ≥ and justify the new strict endpoint.｜否定帶 ≥ 的命題，解釋新式為何用嚴格端點。','On this interval 0≤x²≤n², with both bounds attained. ∀x:x²>k holds iff k<0; ∃x:x²>k holds iff k<n². Their negations are the complementary conditions.｜區間上 0≤x²≤n² 且兩界可取；全稱 >k 當且僅當 k<0，存在 >k 當且僅當 k<n²；否定正好取互補條件。','Use k=0 to expose the missing equality in an incorrect negation.｜用 k=0 揭示錯誤否定遺漏等號的問題。','Negate “every real x has x²>0”.｜否定「每個實數 x 都有 x²>0」。','There exists a real x with x²≤0; x=0 is a witness.｜存在實數 x 使 x²≤0；x=0 是見證。',[C('Negate all｜否定全稱',{n:2,k:1,quantifier:'all'}),C('Equality is essential｜等號不可少',{n:2,k:0,quantifier:'all'},true),C('Negate existence at the maximum｜最大值處否定存在',{n:2,k:4,quantifier:'exists'},true)],[N('n','Interval bound n｜區間上界 n',1,5),N('k','Threshold k｜門檻 k',-2,30),S('quantifier','Original quantifier｜原量詞',[['all','For every x｜對每個 x'],['exists','For at least one x｜至少存在一個 x']])],'Quantifiers and strict inequalities｜量詞與嚴格不等式'),
 A('03',1,'Does the middle always solve it?｜一定取兩根之間嗎？','What changes when the leading coefficient changes sign?｜首項係數變號後會怎樣？','For a(x−r)(x−s)≤0, keep r,s fixed and compare positive, negative and zero a.｜對 a(x−r)(x−s)≤0，固定 r、s，比較 a 正、負、零。','Two distinct factors change sign at their roots; a negative multiplier reverses the product sign.｜兩個不同因子在零點變號；負乘數使乘積符號反轉。','Roots are real. a=0 is a constant-zero expression and is classified separately.｜零點為實數；a=0 時式子恆為零，另作分類。','“Take the middle” assumes positive leading coefficient and two distinct roots.｜「取中間」假設首項係數正且有兩個不同根。','Explain the repeated-root case without appealing to the graph.｜不用圖像，說明重根情況。','Order the roots u≤v. On each interval the signs of x−u and x−v are fixed. Multiplication gives the sign chart, while root substitution decides endpoints.｜把根排序 u≤v；各區間中兩因子符號固定；相乘得符號表，代根決定端點。','Have one pupil explain the graph and another explain factor signs.｜請一人用圖像、另一人用因子符號說明。','Solve −(x−1)(x−4)≤0.｜解 −(x−1)(x−4)≤0。','x≤1 or x≥4, including both roots.｜x≤1 或 x≥4，包括兩根。',[C('Positive coefficient｜正首項係數',{a:1,r:-2,s:3}),C('Negative coefficient｜負首項係數',{a:-1,r:-2,s:3}),C('Zero coefficient｜零首項係數',{a:0,r:-2,s:3},true)],[N('a','Leading coefficient a｜首項係數 a',-3,3),N('r','Root r｜零點 r',-5,5),N('s','Root s｜零點 s',-5,5)],'Factor signs and number lines｜因子符號與數線'),
 A('03',2,'How many real zeros?｜有多少個實零點？','Can a quadratic be positive without crossing the axis?｜二次式不穿過橫軸，仍可以為正嗎？','Change c in ax²+bx+c; predict two, one or no real zeros before revealing Δ.｜改變 ax²+bx+c 的 c，顯示 Δ 前先預測有兩個、一個或沒有實零點。','The discriminant counts real zeros for a≠0. If a=0, the expression is linear or constant, so use its own rule.｜a≠0 時判別式決定實零點數；a=0 時變為一次或常數，須另判。','a,b,c are real numbers; quadratic classification requires a≠0.｜a、b、c 為實數；二次分類要求 a≠0。','A graph outside the current viewing window is not evidence that a root is absent.｜零點不在目前視窗內，不代表零點不存在。','Use completing the square to explain why a repeated root does not reverse sign.｜用配方說明重根處為何不變號。','For a≠0, ax²+bx+c=a[(x+b/(2a))²−Δ/(4a²)]. A square equals Δ/(4a²) at zeros, yielding two, one or zero real roots according to Δ.｜a≠0 時，配方為 a[(x+b/(2a))²−Δ/(4a²)]；零點要求平方等於 Δ/(4a²)，按 Δ 正、零、負得兩、一、零個實根。','Ask for a numerical invariant deciding the root count beyond the plotted samples.｜請找能超越有限畫面取樣、決定根數的量。','How many real zeros does x²+1 have? What sign does it have?｜x²+1 有多少實零點？它的符號如何？','No real zero; it is at least 1 and therefore strictly positive.｜沒有實零點；其值至少 1，因此恆正。',[C('Two zeros｜兩零點',{a:1,b:0,c:-1}),C('A repeated root｜重根',{a:1,b:-2,c:1},true),C('No real zero｜沒有實零點',{a:1,b:0,c:1},true),C('Linear degeneration｜退化為一次式',{a:0,b:2,c:-2},true)],[N('a','Coefficient a｜係數 a',-3,3),N('b','Coefficient b｜係數 b',-5,5),N('c','Constant c｜常數 c',-5,5)],'Quadratic equations and squares｜二次方程與平方'),
 A('03',3,'Do the endpoints belong?｜端點應否包括？','What is the difference between < and ≤ at a root?｜在零點處，< 與 ≤ 有何分別？','Keep the same polynomial and change only the inequality symbol.｜固定同一多項式，只更換不等號。','A root gives exactly zero, so it belongs precisely when equality is allowed. Repeated roots need their own sign analysis.｜零點的值恰為零，只在容許等號時納入；重根仍須另作符號分析。','Use a(x−r)(x−s) with real parameters, including a=0.｜使用實參數 a(x−r)(x−s)，包括 a=0。','Open endpoints are not approximate exclusions; they exclude exactly the root.｜空心端點不是大約不包括，而是恰好排除零點。','Classify all four inequalities for (x−2)².｜分類 (x−2)² 的四種不等式。','At any nonroot the strict and non-strict versions have the same sign test. At each root the value is 0; comparing 0 with 0 gives its inclusion exactly.｜非根處嚴格與非嚴格版本的符號判準相同；根處值為 0，由 0 與 0 的比較精確決定納入。','Ask pupils to substitute each endpoint instead of memorising bracket patterns.｜請代入端點決定括號，不靠背誦。','Solve (x−2)²<0 and (x−2)²≤0.｜解 (x−2)²<0 與 (x−2)²≤0。','The first has no solution; the second has the singleton {2}.｜前者無解；後者解集為 {2}。',[C('Strict inequality｜嚴格不等式',{a:1,r:1,s:4,relation:'lt'}),C('Include equality｜包括等號',{a:1,r:1,s:4,relation:'le'}),C('Repeated root｜重根',{a:1,r:2,s:2,relation:'lt'},true)],[N('a','Coefficient a｜係數 a',-3,3),N('r','Root r｜零點 r',-5,5),N('s','Root s｜零點 s',-5,5),S('relation','Inequality｜不等式',[['lt','Less than zero｜小於零'],['le','At most zero｜小於或等於零'],['gt','Greater than zero｜大於零'],['ge','At least zero｜大於或等於零']])],'Root signs and endpoint notation｜零點符號與端點記法'),
 A('03',4,'A profitable value may be impossible｜獲利數值也可能不可行','Which non-loss solutions are feasible in the context?｜不虧損的解，哪些符合情境限制？','Predict the feasible set for P(x)=a(x−r)(x−s)≥0 under 0≤x≤d, then require integer x.｜預測 P(x)=a(x−r)(x−s)≥0 且 0≤x≤d 的可行集，再限制 x 為整數。','The final choice is the intersection of the sign solution, the contextual interval and, when required, the integers.｜最後選擇是符號解集、情境區間及所需整數集的交集。','The profit expression is a mathematical scenario; d≥1 and the integer restriction is explicit.｜收益式是自編數學情境；d≥1，整數限制須明示。','A real root outside the contextual domain is not a feasible activity size.｜情境域外的實根不是可行活動規模。','Find parameters with real feasible values but no feasible integer.｜找一組參數，使有實數可行值但沒有可行整數。','An x is acceptable iff it satisfies every constraint. Solving the polynomial first and intersecting cannot add an input failing any original condition.｜可接受的 x 須同時符合全部條件；先解多項式再取交集，不會加入違反原條件的輸入。','Ask students to circle which restriction removes each rejected candidate.｜請學生圈出每個候選值被哪項限制排除。','P(x)=−(x−2)(x−8), 0≤x≤6. Find feasible integer non-loss sizes.｜P(x)=−(x−2)(x−8)，0≤x≤6；求不虧損的可行整數規模。','2,3,4,5,6. The contextual upper bound removes 7 and 8.｜2、3、4、5、6；情境上界排除 7、8。',[C('Continuous scale｜連續規模',{a:-1,r:2,s:8,d:10,integer:'no'}),C('Capacity binds｜容量限制',{a:-1,r:2,s:8,d:6,integer:'yes'}),C('Repeated root is the only choice｜重根為唯一選擇',{a:-1,r:3,s:3,d:6,integer:'yes'},true)],[N('a','Coefficient a｜係數 a',-2,2),N('r','Root r｜零點 r',-2,12,.5),N('s','Root s｜零點 s',-2,12,.5),N('d','Capacity d｜容量 d',1,20),S('integer','Allowed sizes｜容許規模',[['no','Real values｜實數'],['yes','Integer values｜整數']])],'Polynomial signs and intersections｜多項式符號與交集'),
 A('04',1,'What does division preserve?｜除法保留甚麼關係？','How can the quotient and remainder reconstruct f?｜商式與餘式如何重組 f？','For a cubic divided by x−a, predict the degree of the quotient and the shape of the remainder.｜三次式除以 x−a，先預測商式次數與餘式形式。','Polynomial division gives f=(x−a)q+r, with constant r. The two plotted curves f and (x−a)q differ vertically by r everywhere.｜多項式除法給出 f=(x−a)q+r，r 為常數；圖上 f 與 (x−a)q 在各處的垂直差均為 r。','The divisor is the nonzero monic polynomial x−a; coefficients are real.｜除式為非零首一多項式 x−a；係數為實數。','The identity holds at a too; only writing f/(x−a)=q+r/(x−a) excludes a.｜恆等式在 a 亦成立；只有分式寫法才排除 a。','Explain why a nonconstant remainder would violate division by a linear polynomial.｜說明一次除式為何不能留下非常數餘式。','Expanding the computed quotient gives coefficient equality for every power. The remainder degree is below one, proving the identity for all real x.｜展開所得商式，逐次方係數相同；餘式次數小於一，因此對所有實數 x 成立。','Point to the constant vertical difference at several positions, then ask for the coefficient proof.｜先指幾處固定垂直差，再要求係數論證。','Divide x²+1 by x−1.｜把 x²+1 除以 x−1。','Quotient x+1, remainder 2; x²+1=(x−1)(x+1)+2.｜商 x+1，餘 2；x²+1=(x−1)(x+1)+2。',[C('Nonzero remainder｜非零餘式',{b:-2,c:0,d:3,a:2}),C('An exact factor｜整除',{b:0,c:-1,d:0,a:1},true),C('Divide by x｜除以 x',{b:2,c:-3,d:4,a:0},true)],[N('b','x² coefficient b｜x² 係數 b',-4,4),N('c','x coefficient c｜x 係數 c',-4,4),N('d','Constant d｜常數 d',-5,5),N('a','Divisor x−a｜除式中的 a',-3,3)],'Polynomial expansion｜多項式展開'),
 A('04',2,'Where did the missing terms go?｜缺項去了哪裏？','Can missing coefficients be omitted in synthetic division?｜綜合除法可否直接省略缺項係數？','For x⁴+bx²+c, predict the five coefficient slots before dividing by x−a.｜對 x⁴+bx²+c，除以 x−a 前先預測五個係數位置。','Missing x³ and x terms have coefficient zero. Keeping their slots preserves the powers during multiply-and-add steps.｜缺少的 x³、x 項係數為零；保留位置才能在乘加步驟中保持次方對齊。','The polynomial has degree four even when b or c is zero. Division is by x−a.｜即使 b 或 c 為零，多項式仍為四次；除式是 x−a。','Removing a zero slot changes the polynomial rather than simplifying its notation.｜刪去零位置會改變多項式，不是簡化記法。','Compare the erroneous division using [1,b,c] with the correct five-slot computation.｜比較錯用 [1,b,c] 與正確五格計算所得結果。','Horner recurrence h₀=1, hᵢ=cᵢ+a hᵢ₋₁ matches successive coefficient cancellation. With zero slots retained, expansion recovers the original coefficients.｜霍納遞推 h₀=1、hᵢ=cᵢ+a hᵢ₋₁ 對應逐項消去；保留零格後，展開會還原原係數。','Ask pupils to label the power above every coefficient before moving counters.｜移動數牌前，請先在每個係數上標次方。','List the coefficient row for x⁴−3x²+2.｜列 x⁴−3x²+2 的係數行。','[1,0,−3,0,2], including both missing terms.｜[1,0,−3,0,2]，兩個缺項均保留。',[C('Two internal zero slots｜兩個內部零格',{b:-3,c:2,a:1}),C('Only x⁴ remains｜只剩 x⁴',{b:0,c:0,a:2},true),C('Zero multiplier｜乘數為零',{b:2,c:-1,a:0},true)],[N('b','x² coefficient b｜x² 係數 b',-4,4),N('c','Constant c｜常數 c',-5,5),N('a','Synthetic multiplier a｜綜合除法乘數 a',-3,3)],'Polynomial coefficient order｜多項式係數次序'),
 A('04',3,'Read a remainder from one point｜由一個點讀出餘式','Why is the remainder f(a)?｜餘式為何是 f(a)？','Divide f(x)=x³+bx+c by x−a; predict which graph input reveals the remainder.｜f(x)=x³+bx+c 除以 x−a；先預測圖上哪個輸入能讀出餘式。','At x=a the quotient term is multiplied by zero, leaving f(a)=r. The sign of a comes from the complete divisor.｜x=a 時商式項乘零，只剩 f(a)=r；a 的正負須由完整除式讀出。','The divisor must be x−a; division by x+a uses input −a.｜除式為 x−a；若是 x+a，則代入 −a。','A point with small output is not necessarily an exact zero.｜輸出很小的點未必是精確零點。','Recover the remainders for x−2 and x+2 without performing long division.｜不用長除法，求除以 x−2 及 x+2 的餘式。','The division identity f=(x−a)q+r is a polynomial identity, so substitution x=a is valid and gives r=f(a) exactly.｜除法關係是多項式恆等式，可合法代 x=a，精確得到 r=f(a)。','Cover the long-division steps and ask why the marked ordinate is sufficient.｜先遮住長除法步驟，問為何只看標記縱坐標便足夠。','Find the remainder of x³+1 divided by x+2.｜求 x³+1 除以 x+2 的餘式。','f(−2)=−8+1=−7.｜f(−2)=−8+1=−7。',[C('Positive a｜正 a',{b:-2,c:3,a:2}),C('Divisor x+2｜除式 x+2',{b:0,c:1,a:-2}),C('Zero remainder｜零餘式',{b:-1,c:0,a:1},true)],[N('b','x coefficient b｜x 係數 b',-4,4),N('c','Constant c｜常數 c',-5,5),N('a','Divisor zero a｜除式零點 a',-3,3)],'Division identity and substitution｜除法恆等式與代入'),
 A('04',4,'Design a factor by changing one coefficient｜改一個係數設計因式','What constant makes x−a a factor?｜哪個常數使 x−a 成為因式？','For x³+kx+c, predict the required c before comparing the original and repaired graphs.｜對 x³+kx+c，先預測所需 c，再比較原圖與修補後的圖。','x−a is a factor iff f(a)=0, so c=−a³−ka. Adjusting c translates the graph vertically.｜x−a 為因式當且僅當 f(a)=0，因此 c=−a³−ka；改 c 使圖像垂直平移。','The leading coefficient stays one; only the constant is repaired.｜首項係數保持一，只修補常數項。','A factor condition is an exact equality, not merely an axis crossing nearby.｜因式條件是精確等式，不是附近看似交軸。','If two different roots are required, determine whether one adjustable constant is sufficient.｜若要求兩個不同根，研究只改一個常數是否足夠。','Remainder theorem gives r=a³+ka+c. The divisor is a factor exactly when r=0, which has the unique displayed solution for c.｜餘式定理給 r=a³+ka+c；除式是因式恰當 r=0，因此 c 有所示唯一解。','Ask pupils to justify both directions of “if and only if”.｜請學生說明「當且僅當」的兩個方向。','Find c so x+1 divides x³+2x+c.｜求 c，使 x+1 整除 x³+2x+c。','Set f(−1)=−1−2+c=0, giving c=3.｜令 f(−1)=−1−2+c=0，得 c=3。',[C('A repair is needed｜需要修補',{a:1,k:2,c:0}),C('Already a factor｜已經是因式',{a:-1,k:2,c:3},true),C('Root at zero｜零為根',{a:0,k:-2,c:0},true)],[N('a','Required root a｜要求的根 a',-3,3),N('k','x coefficient k｜x 係數 k',-3,3),N('c','Original constant c｜原常數 c',-40,40)],'Remainder theorem｜餘式定理'),
 A('11',1,'Which power controls the multiplier?｜哪個次方決定倍率？','Does doubling x always double y?｜x 加倍，y 必定加倍嗎？','For y=kxⁿ, predict y(2x)/y(x) for n=1,2,3.｜對 y=kxⁿ，預測 n=1、2、3 時 y(2x)/y(x)。','The fixed invariant is y/xⁿ=k. Doubling x multiplies y by 2ⁿ when a ratio is defined.｜不變量為 y/xⁿ=k；比例有定義時，x 加倍令 y 乘 2ⁿ。','Here x>0 and n∈{1,2,3}. If k=0, both outputs vanish and their ratio is undefined.｜此處 x>0、n∈{1,2,3}；k=0 時兩輸出皆零，比值沒有定義。','“Directly proportional to x²” means kx², not (kx)².｜「與 x² 成正變」指 kx²，不是 (kx)²。','Use a noninteger positive scale t and derive the multiplier tⁿ.｜改用正的非整數倍 t，推出倍率 tⁿ。','k(2x)ⁿ=2ⁿkxⁿ by exponent laws. Dividing requires y(x)≠0; the identity itself also holds at k=0.｜由指數律，k(2x)ⁿ=2ⁿkxⁿ；相除要求 y(x)≠0，但原恆等式在 k=0 仍成立。','Distinguish an output identity from a ratio that may be undefined.｜區分輸出恆等式與可能無定義的比值。','y=3x². If x is tripled, what happens to y?｜y=3x²；x 變三倍，y 怎樣變？','y becomes nine times as large.｜y 變為九倍。',[C('Linear direct variation｜一次正變',{k:2,n:1,x:1}),C('Square variation｜平方正變',{k:2,n:2,x:1}),C('Zero proportionality constant｜比例常數為零',{k:0,n:3,x:2},true)],[N('k','Constant k｜常數 k',-3,3),S('n','Power n｜次方 n',[[1,'One｜一'],[2,'Two｜二'],[3,'Three｜三']]),N('x','Positive input x｜正輸入 x',.5,4,.5)],'Powers and ratios｜乘方與比'),
 A('11',2,'A fixed product instead of a fixed ratio｜固定乘積而非固定比','What remains fixed in inverse variation?｜反變中哪個量保持不變？','Predict the new output when x is multiplied by t in y=k/x.｜在 y=k/x 中，x 乘 t 後先預測新輸出。','The product xy=k is fixed; for nonzero t the new output is y/t. x=0 is excluded.｜乘積 xy=k 固定；非零 t 下，新輸出為 y/t；x=0 被排除。','x≠0 and t>0; even if k=0, the original expression k/x remains undefined at zero.｜x≠0、t>0；即使 k=0，原式 k/x 在零仍沒有定義。','Multiplying x by two does not subtract a fixed amount from y.｜x 乘二不是令 y 減少一個固定量。','Compare negative and positive x while retaining the same k.｜保持同一 k，比較負與正 x。','(tx)·[k/(tx)]=k and k/(tx)=(k/x)/t, under the nonzero-denominator conditions.｜在分母非零條件下，(tx)·[k/(tx)]=k，且 k/(tx)=(k/x)/t。','Ask what survives algebraic simplification when the input is zero.｜輸入為零時，問代數化簡能否取消原限制。','y=12/x. Find y at x=3 and x=6.｜y=12/x；求 x=3、6 時的 y。','4 and 2 respectively; both products xy equal 12.｜分別為 4、2；兩者 xy 均等於 12。',[C('Double a positive input｜正輸入加倍',{k:4,x:1,t:2}),C('Negative input｜負輸入',{k:4,x:-2,t:2}),C('Excluded zero input｜排除零輸入',{k:0,x:0,t:2},true)],[N('k','Constant k｜常數 k',-4,4),N('x','Input x｜輸入 x',-4,4,.5),N('t','Input multiplier t｜輸入倍率 t',.5,3,.5)],'Division and domain restrictions｜除法與定義域限制'),
 A('11',3,'Change one factor or both?｜改一個因子還是兩個？','In joint variation, do two doublings still give a doubling?｜聯變中兩個量都加倍，結果還是只加倍嗎？','For y=kxz, compare doubling x alone with doubling both x and z.｜對 y=kxz，比較只把 x 加倍與把 x、z 同時加倍。','One doubled factor doubles y; two doubled factors multiply y by four. Zero inputs remain legitimate but can make ratios undefined.｜一個因子加倍使 y 加倍；兩者加倍使 y 乘四；零輸入仍合法，但比值可能無定義。','k,x,z are real; y/(xz) is used only when xz≠0.｜k、x、z 為實數；y/(xz) 只在 xz≠0 時使用。','Joint variation requires specifying which variables are held fixed.｜聯變必須說明哪些變數保持不變。','Let x scale by s and z by t; determine the combined multiplier.｜x 乘 s、z 乘 t，求合併倍率。','k(sx)(tz)=st(kxz) by associativity and commutativity. This identity does not divide by any potentially zero output.｜由乘法結合及交換律，k(sx)(tz)=st(kxz)；此恆等式毋須除以可能為零的輸出。','Ask groups to alter just one factor before altering both.｜請小組先只改一個因子，再同時改兩者。','y=2xz; initially x=3,z=4. What if x doubles and z halves?｜y=2xz；原 x=3、z=4；x 加倍、z 減半會怎樣？','y stays 24 because the two multipliers have product one.｜y 仍為 24，因兩倍率乘積為一。',[C('Two nonzero factors｜兩個非零因子',{k:2,x:1,z:2}),C('A negative factor｜一個負因子',{k:2,x:-1,z:2}),C('A zero factor｜零因子',{k:2,x:0,z:2},true)],[N('k','Constant k｜常數 k',-3,3),N('x','Input x｜輸入 x',-3,3),N('z','Input z｜輸入 z',-3,3)],'Products and direct variation｜乘積與正變'),
 A('11',4,'The fixed part changes the ratio｜固定部分改變比值','Does a straight graph always mean direct proportion?｜直線圖像必定表示正比嗎？','Compare y=a+bx with y=bx while keeping the same rate b.｜保持相同變化率 b，比較 y=a+bx 與 y=bx。','A fixed part a gives y(0)=a. Equal x increments give equal output increments, but output ratios are not generally fixed.｜固定部分 a 使 y(0)=a；相等輸入增量給相等輸出增量，但輸出比未必固定。','x is nonnegative; a and b are model parameters, not measured empirical facts.｜x 非負；a、b 是模型參數，不是實測事實。','Linearity with an intercept is not the same as direct proportionality through the origin.｜帶截距的直線關係不等於過原點的正比關係。','From two input-output pairs, identify a and b and test a third pair.｜由兩組輸入輸出求 a、b，再檢查第三組。','y(2x)−2y(x)=−a, so doubling outputs holds for all x iff a=0. Also y(x+h)−y(x)=bh.｜y(2x)−2y(x)=−a，因此對所有 x 輸出加倍當且僅當 a=0；另有 y(x+h)−y(x)=bh。','Ask students to identify the initial amount before comparing per-unit rates.｜比較每單位費率前，先辨認起始量。','A charge is 20+3x. Compare x=2 and x=4.｜費用為 20+3x；比較 x=2 與 x=4。','26 and 32; doubling x does not double the fixed 20.｜26 與 32；x 加倍不會使固定 20 加倍。',[C('A fixed starting amount｜固定起始量',{a:3,b:2,x:2}),C('Direct variation boundary｜正變邊界',{a:0,b:2,x:2},true),C('Zero input｜零輸入',{a:3,b:2,x:0},true)],[N('a','Fixed part a｜固定部分 a',-4,6),N('b','Rate b｜變化率 b',-3,3),N('x','Input x｜輸入 x',0,4,.5)],'Affine functions and ratios｜仿射函數與比'),
 A('12',1,'Which factor copies are shared?｜哪些因式副本是共有的？','Why does a greatest common divisor use the lower exponent?｜最大公因式為何取較低次冪？','Build A=(x−1)ᵐ(x+1)ⁿ and B=(x−1)ᵖ(x+1)ᑫ; predict their shared tiles.｜建立 A=(x−1)ᵐ(x+1)ⁿ、B=(x−1)ᵖ(x+1)ᑫ，預測共有因式牌。','A common divisor cannot use more copies than either polynomial contains, so it uses the minimum exponent of each factor.｜公因式不能比任一多項式有更多副本，因此各因式取最低次冪。','Both polynomials are monic and nonzero. Exponent zero contributes the factor 1.｜兩式首一且非零；零次方提供因式 1。','Greatest refers to divisibility, not whichever evaluated number is largest.｜「最大」指整除關係，不是代入後哪個數最大。','Show that every common divisor divides the displayed greatest common divisor.｜說明每個公因式都整除所示最大公因式。','For each distinct irreducible factor, a common divisor exponent is at most both source exponents, hence at most their minimum. The constructed product itself divides both.｜對每個不同不可約因式，公因式次冪不超過兩原式次冪，因此不超過最小值；所建乘積本身亦整除兩式。','Request a divisibility check by subtracting factor counts.｜請用因式數量相減來檢查整除。','Find the monic GCD of (x−1)²(x+1) and (x−1)(x+1)³.｜求 (x−1)²(x+1) 與 (x−1)(x+1)³ 的首一最大公因式。','(x−1)(x+1).｜(x−1)(x+1)。',[C('Two shared factors｜兩個共有因式',{m:2,n:1,p:1,q:3}),C('Coprime factors｜互質因式',{m:2,n:0,p:0,q:2},true),C('One polynomial is one｜一式為一',{m:0,n:0,p:2,q:1},true)],[N('m','A: exponent of x−1｜A 中 x−1 次冪',0,3),N('n','A: exponent of x+1｜A 中 x+1 次冪',0,3),N('p','B: exponent of x−1｜B 中 x−1 次冪',0,3),N('q','B: exponent of x+1｜B 中 x+1 次冪',0,3)],'Factorisation and divisibility｜因式分解與整除'),
 A('12',2,'The smallest shared multiple｜最少需要哪些因式？','Why is multiplying A and B usually excessive?｜直接把 A、B 相乘，為何通常用多了因式？','Compare all factor copies in AB with the copies needed by a common multiple.｜比較 AB 的全部因式副本，與公倍式真正需要的副本。','A common multiple must contain enough copies for both source polynomials, so each exponent is the maximum, not the sum.｜公倍式須有足夠副本供兩原式整除，因此各次冪取最大值而非相加。','All polynomials are monic and nonzero, with only the displayed distinct factors.｜所有多項式首一且非零，只含所示兩個不同因式。','A multiple need not include two separate copies of a factor already shared.｜已共有的因式不一定要再重複保留兩份。','Verify GCD(A,B)·LCM(A,B)=AB factor by factor.｜逐因式驗證 GCD(A,B)·LCM(A,B)=AB。','A common-multiple exponent is at least both source exponents, hence at least their maximum. The construction attains it; min(u,v)+max(u,v)=u+v proves the product identity.｜公倍式次冪至少是兩原式次冪，因此至少取最大值；構造達到此界，而 min(u,v)+max(u,v)=u+v 證明乘積關係。','Ask which factor can be removed without losing either divisibility requirement.｜問能否刪一張因式牌而仍符合兩項整除要求。','Find the monic LCM of x−1 and (x−1)².｜求 x−1 與 (x−1)² 的首一最小公倍式。','(x−1)², not (x−1)³.｜(x−1)²，不是 (x−1)³。',[C('Shared and unshared copies｜共有與非共有副本',{m:2,n:1,p:1,q:3}),C('Equal polynomials｜兩式相等',{m:2,n:1,p:2,q:1},true),C('One polynomial is one｜一式為一',{m:0,n:0,p:2,q:1},true)],[N('m','A: exponent of x−1｜A 中 x−1 次冪',0,3),N('n','A: exponent of x+1｜A 中 x+1 次冪',0,3),N('p','B: exponent of x−1｜B 中 x−1 次冪',0,3),N('q','B: exponent of x+1｜B 中 x+1 次冪',0,3)],'GCD and factor counts｜最大公因式與因式計數'),
 A('12',3,'Why do remainders preserve the GCD?｜餘式為何保留最大公因式？','Can replacing A by a remainder lose a common factor?｜用餘式替換 A，會遺失公因式嗎？','Start with A=(x−r)(x²+u), B=(x−r)(x+v); predict the final nonzero remainder.｜由 A=(x−r)(x²+u)、B=(x−r)(x+v) 開始，預測最後非零餘式。','The last nonzero Euclidean remainder, made monic, is the GCD. Sometimes B already divides A.｜輾轉相除最後一個非零餘式首一化後是最大公因式；有時 B 已整除 A。','The displayed polynomials are nonzero; each remainder has smaller degree. The zero remainder terminates the algorithm.｜所示多項式非零；每步餘式次數下降；零餘式使演算法結束。','A zero remainder is not itself the GCD; use the preceding nonzero divisor.｜零餘式本身不是最大公因式，應取前一非零除式。','Find a condition on u,v that makes the GCD quadratic rather than linear.｜找 u、v 的條件，使最大公因式為二次而非一次。','If A=BQ+R, a divisor common to A,B divides R=A−BQ; conversely a divisor of B,R divides A. Repetition preserves all common divisors until termination.｜若 A=BQ+R，A、B 的公因式整除 R=A−BQ；反之 B、R 的公因式整除 A；反覆應用至終止，保留全部公因式。','After every arrow, ask pupils to justify the same-common-divisors claim in both directions.｜每條箭頭後，請說明公因式集合不變的兩個方向。','Why do A and B have the same GCD as B and A−B?｜A、B 為何與 B、A−B 有相同最大公因式？','A common divisor of A,B divides A−B; a common divisor of B,A−B divides their sum A.｜A、B 的公因式整除 A−B；B、A−B 的公因式整除兩者和 A。',[C('A linear GCD｜一次最大公因式',{r:1,u:1,v:2}),C('B divides A｜B 整除 A',{r:1,u:-1,v:1},true),C('A root at zero｜零為共有根',{r:0,u:0,v:0},true)],[N('r','Shared root r｜共有根 r',-3,3),N('u','Constant u in x²+u｜x²+u 中 u',-3,4),N('v','Constant v in x+v｜x+v 中 v',-3,3)],'Polynomial division and factors｜多項式除法與因式'),
 A('13',1,'Two denominators, one identity｜兩個分母，一條恆等式','How can substituting a forbidden value still find a coefficient?｜禁值為何仍可用來求係數？','Decompose (mx+n)/[(x−a)(x−b)]; predict what remains in the numerator identity at x=a.｜分解 (mx+n)/[(x−a)(x−b)]；預測分子恆等式在 x=a 時留下甚麼。','After clearing denominators, mx+n=A(x−b)+B(x−a) is a polynomial identity. Substitution there is valid even at a or b.｜消分母後，mx+n=A(x−b)+B(x−a) 是多項式恆等式，在 a、b 處亦可合法代入。','a≠b; the original fractions require x≠a,b.｜a≠b；原分式要求 x≠a,b。','Do not substitute a forbidden value into the original rational expression.｜不可把禁值代入原有理式。','Recover A and B by coefficient comparison instead of special-value substitution.｜不用特殊值代入，改用比較係數求 A、B。','Putting x=a gives A=(ma+n)/(a−b); x=b gives B=(mb+n)/(b−a). These coefficients also satisfy A+B=m and −Ab−Ba=n.｜代 x=a 得 A=(ma+n)/(a−b)，代 x=b 得 B=(mb+n)/(b−a)；所得係數亦滿足 A+B=m、−Ab−Ba=n。','Point explicitly to the expression in which the substitution is performed.｜明確指出正在把數值代入哪一個式子。','Decompose 1/[x(x+1)].｜分解 1/[x(x+1)]。','1/x−1/(x+1), retaining x≠0,−1.｜1/x−1/(x+1)，保留 x≠0,−1。',[C('Distinct linear factors｜不同一次因式',{a:0,b:-1,m:0,n:1}),C('A numerator cancellation｜分子可約去因式',{a:1,b:-1,m:1,n:-1},true),C('Repeated factors need a new form｜重複因式須換形式',{a:1,b:1,m:1,n:2},true)],[N('a','First root a｜第一根 a',-3,3),N('b','Second root b｜第二根 b',-3,3),N('m','Numerator coefficient m｜分子係數 m',-3,3),N('n','Numerator constant n｜分子常數 n',-3,3)],'Rational domains and coefficient identities｜有理式定義域與係數恆等式'),
 A('13',2,'Why include every repeated power?｜重因式為何逐次冪列出？','Can one term represent every numerator over (x−a)²?｜一項分式足以表示分母 (x−a)² 的任何一次分子嗎？','Compare A/(x−a)+B/(x−a)² with the incomplete proposal B/(x−a)².｜比較 A/(x−a)+B/(x−a)² 與只保留 B/(x−a)² 的提案。','For numerator mx+n, coefficient comparison gives A=m and B=ma+n. Dropping A removes an entire variable term unless m=0.｜分子為 mx+n 時，比較係數得 A=m、B=ma+n；除非 m=0，刪 A 會漏掉變量項。','x≠a. The repeated-root form is used even if a numerator cancellation is possible.｜x≠a；即使分子可約去因式，仍使用重根形式。','One numerical match does not prove an identity of rational expressions.｜一個數值吻合不能證明有理式恆等。','Generalise the template to denominator (x−a)³.｜把設式形式推廣至分母 (x−a)³。','Clearing denominators gives mx+n=A(x−a)+B. The x coefficient forces A=m; the constant then forces B=n+ma.｜消分母得 mx+n=A(x−a)+B；x 係數要求 A=m，常數要求 B=n+ma。','Show the incorrect graph as well as the corrected graph and ask for the missing coefficient.｜同時展示錯誤與修正圖像，請找漏掉的係數。','Decompose x/(x−1)².｜分解 x/(x−1)²。','1/(x−1)+1/(x−1)², with x≠1.｜1/(x−1)+1/(x−1)²，x≠1。',[C('Both powers are needed｜兩個次冪都需要',{a:1,m:1,n:0}),C('First coefficient is zero｜一次項係數為零',{a:1,m:0,n:2},true),C('Second coefficient is zero｜二次項係數為零',{a:1,m:1,n:-1},true)],[N('a','Repeated root a｜重根 a',-3,3),N('m','Numerator coefficient m｜分子係數 m',-3,3),N('n','Numerator constant n｜分子常數 n',-3,3)],'Coefficient comparison｜比較係數'),
 A('13',3,'Divide before decomposing｜先除法，再分解','Where does the polynomial part come from?｜多項式部分從何而來？','Compare the degrees of x²+px+q and (x−a)(x−b); predict the missing polynomial term.｜比較 x²+px+q 與 (x−a)(x−b) 次數，預測不可遺漏的多項式項。','The quotient is 1. Only the lower-degree remainder is decomposed into simple fractions.｜商為 1；只有較低次餘式才再拆為簡單分式。','a≠b and x≠a,b. The numerator and denominator are monic quadratics.｜a≠b、x≠a,b；分子及分母均為首一二次式。','A sum of these proper fractions cannot reproduce the nonzero limiting polynomial part.｜這些真分式的和不能重現非零多項式部分。','Explain the horizontal limiting value without assuming the graph proves it.｜不用圖像作證，說明水平趨近值。','Subtracting the denominator leaves (p+a+b)x+(q−ab). Thus the original ratio is 1 plus that remainder ratio; the distinct-root coefficient identities then verify the decomposition.｜減去分母後餘 (p+a+b)x+(q−ab)；原比值等於 1 加此餘式比，再由不同根係數恆等式驗證拆式。','Ask what remains when x becomes large and the proper fractions become small.｜問 x 很大、真分式很小時，還留下甚麼。','Rewrite x²/[x(x−1)] as a polynomial plus simple fractions.｜把 x²/[x(x−1)] 寫成多項式加簡單分式。','1+1/(x−1), retaining x≠0,1.｜1+1/(x−1)，仍保留 x≠0,1。',[C('A nonzero remainder｜非零餘式',{p:2,q:3,a:1,b:-1}),C('Zero remainder, two holes｜餘式零但仍有兩禁值',{p:0,q:-1,a:1,b:-1},true),C('A cancelled factor｜可約去一因式',{p:0,q:0,a:0,b:1},true)],[N('p','Numerator coefficient p｜分子係數 p',-3,3),N('q','Numerator constant q｜分子常數 q',-4,4),N('a','First root a｜第一根 a',-3,3),N('b','Second root b｜第二根 b',-3,3)],'Polynomial division and simple fractions｜多項式除法與簡單分式'),
 A('13',4,'Does cancellation repair a hole?｜約分能填補空點嗎？','Are equal values on a shared domain the same as equal domains?｜共同定義域上數值相等，是否等於定義域相同？','Compare (x−a)(x+c)/[(x−a)(x−b)] with (x+c)/(x−b), especially at x=a.｜比較 (x−a)(x+c)/[(x−a)(x−b)] 與 (x+c)/(x−b)，特別檢查 x=a。','Cancellation preserves values only at original allowed inputs. The simplified formula may extend the domain, but the original hole remains excluded.｜約分只保留原容許輸入的值；簡式可以延伸定義域，但原空點仍須排除。','a≠b. Original domain excludes a,b; the written simplified formula still excludes b.｜a≠b；原定義域排除 a、b，所寫簡式仍排除 b。','A removable discontinuity is not permission to redefine the original function silently.｜可去間斷不代表可暗中重新定義原函數。','Choose c=−b and classify what remains at both excluded inputs.｜選 c=−b，分類兩個被排除輸入的情況。','The factor x−a is nonzero on the original domain, so division by it is legal there. At x=a the original denominator vanishes regardless of the finite simplified value.｜原定義域內 x−a 非零，可合法約去；x=a 時原分母為零，不受簡式值有限與否影響。','Ask pupils to write both domains before comparing the plotted curves.｜比較兩條圖像前，先寫各自定義域。','Is (x²−1)/(x−1) the same function as x+1 on R?｜(x²−1)/(x−1) 與 R 上的 x+1 是同一函數嗎？','No; the original excludes 1, although the values agree elsewhere.｜不是；原式排除 1，雖然其他位置數值相同。',[C('A normal allowed input｜一般容許輸入',{a:1,b:-1,c:2,x:0}),C('The cancelled root｜被約去的根',{a:1,b:-1,c:2,x:1},true),C('Both singularities are removable｜兩處均可去',{a:1,b:-1,c:1,x:-1},true)],[N('a','Cancelled root a｜約去的根 a',-3,3),N('b','Remaining denominator root b｜餘下分母根 b',-3,3),N('c','Numerator shift c｜分子平移 c',-3,3),N('x','Probe input x｜探測輸入 x',-4,4,.5)],'Domains, cancellation and function equality｜定義域、約分與函數相等'),
];

const byId=new Map(activities.map(a=>[a.id,a]));
const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[ch]));
const fmt=value=>value===null?'—':Number.isFinite(value)?(Math.abs(value)<1e-10?'0':Number(value.toFixed(5)).toString()):'—';
const color={ink:'#263c36',green:'#416b53',orange:'#b36a36',red:'#a63245',pale:'#e8efe9',blue:'#376986'};
const txt=(x,y,text,fill=color.ink,size=17)=>`<text x="${x}" y="${y}" fill="${fill}" font-size="${size}" font-family="system-ui,sans-serif">${esc(text)}</text>`;
const line=(x1,y1,x2,y2,stroke=color.green,width=2,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${stroke}" stroke-width="${width}"${dash?` stroke-dasharray="${dash}"`:''}/>`;
const dot=(x,y,fill=color.orange,r=6,open=false)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${open?'white':fill}" stroke="${fill}" stroke-width="2"/>`;
const rect=(x,y,w,h,fill=color.pale,stroke=color.green)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="${fill}" stroke="${stroke}"/>`;
function svg(title,body){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 340" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><rect width="720" height="340" fill="#fbfcfa"/>${body}</svg>`;}
